CREATE OR ALTER PROCEDURE [dbo].[uspMenu_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @CompanyId UNIQUEIDENTIFIER = NULL
	, @Code NVARCHAR(MAX) = NULL
	, @Name NVARCHAR(MAX) = NULL
	, @MenuType NVARCHAR(MAX) = NULL
	, @VersionCode NVARCHAR(MAX) = NULL
	, @EffectiveFrom DATETIME = NULL
	, @EffectiveTo DATETIME = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[Code]
			, t.[Name]
			, t.[VersionNo]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[Status]
			, t.[Note]
			, t.[CompanyId]
			, j1.[Name] AS [CompanyName]
			, t.[MenuType]
			, t.[VersionCode]
			, t.[CreatedDate]
		FROM [dbo].[Menu] AS t
		LEFT JOIN [dbo].[Company] AS j1 ON j1.[Id] = t.[CompanyId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%') OR t.[VersionCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@CompanyId IS NULL OR t.[CompanyId] = @CompanyId)
			AND (ISNULL(@Code, '') = '' OR t.[Code] LIKE CONCAT('%', @Code, '%'))
			AND (ISNULL(@Name, '') = '' OR t.[Name] LIKE CONCAT('%', @Name, '%'))
			AND (ISNULL(@MenuType, '') = '' OR t.[MenuType] LIKE CONCAT('%', @MenuType, '%'))
			AND (ISNULL(@VersionCode, '') = '' OR t.[VersionCode] LIKE CONCAT('%', @VersionCode, '%'))
			AND (@EffectiveFrom IS NULL OR t.[EffectiveFrom] = @EffectiveFrom)
			AND (@EffectiveTo IS NULL OR t.[EffectiveTo] = @EffectiveTo)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'versionNo' THEN r.[VersionNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'versionNo' THEN r.[VersionNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'companyId' THEN r.[CompanyId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'companyId' THEN r.[CompanyId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'companyName' THEN r.[CompanyName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'companyName' THEN r.[CompanyName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'menuType' THEN r.[MenuType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'menuType' THEN r.[MenuType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'versionCode' THEN r.[VersionCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'versionCode' THEN r.[VersionCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
